import Root from "./1Adding Interactivity/5UpdatingArrays"
import Sub from "./subReLearn"
import "./ReLearn.css"
import { useState } from "react"

export default function () {
  return (
    <>
    <Screen/>
    </>
  );
}

export function Screen() {
  const [obj, setObj] = useState([{val: "king"}])
  const [rewrite, setRewrite] = useState("")
  return (
    <>
    <input onChange={(e) => {setRewrite({val: e.target.value})}}/>
    <input type="submit"
    onClick={() => {
      setObj([
        ...obj.slice(0,1),
        rewrite
      ])
    }}
    />
    {obj.map(e => <div>
      {e.val}
    </div>)}
    </>
  );
}



// http://localhost:3000
